HEAD={'reveal':['تمريض منطقة الخليج','مصمَّم<br>لاختبارات الخليج'],'guide':['دليل خاص بكل اختبار','اختباركم<br>بقواعده'],'wrong':['بنك الأسئلة','تعلّموا السبب<br>لا الإجابة فقط'],'sim':['محاكاة الاختبار','تدرّبوا على<br>اليوم الحقيقي'],'tools':['أدوات القرار','67 أداة<br>قرار'],'poster':['ادرسوا وعدّلوا','علّموا على<br>كل ملصق'],'arabic':['مسرد ثنائي اللغة','English ⇄<br>العربية'],'progress':['مؤشّر الجاهزية','تدرّبوا على ما<br>يرفع درجتكم'],'reset':['الاستراحة والتجديد','حافظوا على<br>هدوئكم'],'compare':['كيف نقارن','ليس مجرد<br>بنك أسئلة'],'price':['سعر بسيط','تُدفع مرة واحدة.<br>لا تتجدّد.']}
c=src
for a,b in TXT:
  assert a in c, a[:60]; c=c.replace(a,b)
c=c.replace("window.SPEC={","window.SPEC={ rtl:true,",1)
blocks=re.split(r"(?=\n  \{id:')",c); out=[]
for blk in blocks:
  m=re.match(r"\n  \{id:'(\w+)'",blk)
  if m:
    i=m.group(1); f=max(0.6,DA[i]/DE[i])
    sc=lambda mm: f"{mm.group(1)}{round(float(mm.group(2))*f,2)}"
    blk=re.sub(r"(\bat:)(-?[\d.]+)",lambda mm: mm.group(1)+str(round(float(mm.group(2))*f,2)) if float(mm.group(2))>0 else mm.group(0),blk)
    blk=re.sub(r"(\bto:)([\d.]+)",sc,blk)
    blk=re.sub(r"\bt:\[([\d.,]+)\]",lambda mm:'t:['+','.join(str(round(float(v)*f,2)) for v in mm.group(1).split(','))+']',blk)
    blk=re.sub(r"(\bstep:)([\d.]+)",sc,blk)
    if i in CAP: blk=re.sub(r"cap:\[(?:\s*'(?:[^'\\]|\\.)*'\s*,?)*\]",lambda mm:'cap:'+json.dumps(CAP[i],ensure_ascii=False),blk,flags=re.S)
    if i in HEAD: blk=re.sub(r"head:\['[^']*','[^']*'\]",'head:'+json.dumps(HEAD[i],ensure_ascii=False),blk)
    blk=re.sub(r"co\((-?[\d.]+),([\d.]+|'end')",lambda mm:'co('+str(round(float(mm.group(1))*f,2))+','+(mm.group(2) if mm.group(2)=="'end'" else str(round(float(mm.group(2))*f,2))),blk)
  out.append(blk)
open('/root/work/v/gmar/config.js','w').write(''.join(out)); print('ok')
